const express = require("express");

// Mỗi nhóm route là một Router riêng (ngoài máy thật: file riêng)
const users = express.Router();
const db = [{ id: 1, name: "An" }];

users.get("/", (req, res) => res.json(db));
users.post("/", (req, res) => {
  const { name } = req.body;
  if (typeof name !== "string" || name.trim().length < 2) {
    return res.status(400).json({ error: "name phải có ít nhất 2 ký tự" });
  }
  const u = { id: db.length + 1, name: name.trim() };
  db.push(u);
  res.status(201).json(u);
});

const app = express();
app.use(express.json());
app.use("/api/users", users);          // gắn Router vào tiền tố /api/users

(async () => {
  const bad = await app.inject({ method: "POST", url: "/api/users", body: { name: "A" } });
  const ok = await app.inject({ method: "POST", url: "/api/users", body: { name: "Bình" } });
  console.log(bad.statusCode, ok.statusCode);
})();

