const express = require("express");
const app = express();
app.use(express.json());

app.post("/signup", (req, res) => {
  const { email, password } = req.body;
  if (!String(email).includes("@") || String(password).length < 6) {
    return res.status(400).json({ error: "invalid" });
  }
  res.status(201).json({ ok: true });
});

(async () => {
  const p = (body) => app.inject({ method: "POST", url: "/signup", body }).then((r) => r.statusCode);
  console.log(await p({ email: "a@b.c", password: "123456" }));
  console.log(await p({ email: "abc", password: "123456" }));
  console.log(await p({ email: "a@b.c", password: "123" }));
})();
